INSERT INTO `news` (`id`, `date`, `time`, `news`, `newsrash`, `key_news`, `fotosmall`, `fotobig`, `bigtext`, `newsrash1`, `dt`, `securit`) VALUES
(524, '25-02-2020', '10:02:51', 'ЗАСЕДАНИЕ КОМИССИИ ПО ПРОТИВОДЕЙСТВИЮ КОРРУПЦИИ В РУП "ГЛАВНЫЙ РАСЧЁТНЫЙ ИНФОРМАЦИОННЫЙ ЦЕНТР» БЕЛОРУССКОЙ ЖЕЛЕЗНОЙ ДОРОГИ ', '', 1, '<p><img src="ed/upload-files/2018/obiaivlenie_70_70.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2018/obiaivlenie_600_300.jpg" alt="" width="600" height="300" /></p>', '<p><strong>ЗАСЕДАНИЕ КОМИССИИ ПО ПРОТИВОДЕЙСТВИЮ КОРРУПЦИИ В РУП "ГЛАВНЫЙ РАСЧЁТНЫЙ ИНФОРМАЦИОННЫЙ ЦЕНТР&raquo; БЕЛОРУССКОЙ ЖЕЛЕЗНОЙ ДОРОГИ НАЗНАЧЕНО НА 26.02.2020 НА 10.00</strong></p>\r\n<p>19 февраля&nbsp; 2020</p>\r\n<p>В соответствии с планом работы комиссии по противодействию коррупции в РУП "Главный расчётный центр" БЖД информируем, что очередное заседание комиссии назначено на 26.02.2020&nbsp;на 10.00.<br /> <br /> Место проведения -&nbsp; кабинет №407 (г.Минск, пер.Стекольный, 5, 4 этаж).</p>', 1, '3165192171', 0),
(525, '28-02-2020', '10:20:38', 'Туристическая экскурсия «ГРОДНО – ГОРОД – МУЗЕЙ»', '', 1, '<p><img src="ed/upload-files/images/grodnos.png" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/images/grodnob.png" alt="" width="672" height="336" /></p>', '<p style="text-align: center;"><strong><em>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  &laquo;ГРОДНО &ndash; ГОРОД &ndash; МУЗЕЙ&raquo;</em></strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong><em>30.04-01.05.2020&nbsp; <span style="color: #ff0000;">1 день в Гродно организуется туристическая экскурсия </span></em></strong></p>\r\n<p><strong><em>Гродно - </em></strong>культурная столица Беларуси, столица белорусских католиков, вторая столица Белорусской народной республики и третья - Речи Посполитой. А еще это один из старейших и привлекательных городов Беларуси, неспроста еще в XVI столетии, Гродно был включен в кельнскую энциклопедию Брауна как один из &laquo;красивейших городов Европы&raquo;. Своего величия Гродно не утратил и в наши дни. Его по праву называют городом-музеем. Исторический центр в 1988 году был объявлен памятником градостроительства и архитектуры. В XVI веке здесь размещалась резиденция короля Речи Посполитой Стефана Батория.<strong><em>&nbsp;</em></strong></p>\r\n<p><strong>!!! Стоимость экскурсии:</strong></p>\r\n<p><strong>На одного 1 человека (при группе 40 чел) 77.00</strong></p>\r\n<p><strong><span style="text-decoration: underline;">В стоимость входит</span></strong><span style="text-decoration: underline;">:</span></p>\r\n<p>- автотранспортное обслуживание по программе <strong>&nbsp;</strong></p>\r\n<p>- экскурсионное&nbsp; обслуживание по программе с входными билетами в музеи&nbsp;&nbsp;&nbsp;&nbsp; <strong>&nbsp;</strong></p>\r\n<p>- питание: 1 <strong>завтрак, 1 обед</strong></p>\r\n<p><em>- </em>катание на теплоходе по Августовскому каналу</p>\r\n<p><br /><strong><img src="ed/upload-files/images/gr.png" alt="" width="159" height="108" /></strong></p>\r\n<p><strong><span style="text-decoration: underline;">Дополнительно оплачивается:</span></strong><strong>&nbsp;</strong></p>\r\n<p><em>- ж/д билеты Минск-Гродно-Минск (плацкарт) + постельное белье - ориентировочно <strong>25,00</strong> (возможно оформление билета по жд требованию)</em></p>\r\n<p>!!! Для членов <strong>профсоюза</strong> и их <strong>детей</strong>&nbsp;<strong>экскурсию&nbsp;</strong>частично оплачивает профсоюз (<strong>40р</strong>).</p>\r\n<p>&nbsp;Профгрупоргам в срок до <strong>15.00 16.03.2020</strong> предоставить списки&nbsp;<strong>желающих принять участие в экскурсии&nbsp;</strong>&laquo;Гродно-город-музей&raquo; на электронный адрес&nbsp;:</p>\r\n<p><a href="mailto:ircst_markovskaya@mnsk.rw">ircst_markovskaya@mnsk.rw</a><strong>Марковская М.В.</strong>, тел. 225-60-13,&nbsp;</p>\r\n<p><a href="mailto:ircst_markovskaya@mnsk.rw">ircm_klimovich@mnsk.rw</a><strong>Климович А.М.</strong>, тел. 225-42-79,&nbsp;</p>\r\n<p><a href="mailto:ircts_panfilenko@mnsk.rw">ircts_panfilenko@mnsk.rw</a><strong>Панфиленко Т. В</strong>., 225-30-16,</p>\r\n<p><a href="mailto:irch_romeiko@mnsk.rw">irch_romeiko@mnsk.rw</a><strong>Ромейко А.Ю</strong>., 225-30-27.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Программа тура и более подробная информация:</strong></p>\r\n<p><strong><br /><a href="ed/upload-files/docs/Grodno 30.04-01.05.2020 gd 1 day (1).doc">Гродно 30.04-01.05.2020 жд 1 день</a><br /></strong></p>\r\n<p><strong><br /><br /></strong></p>\r\n<p><strong><br /><br /></strong></p>', 1, '3165711638', 0),
(529, '06-03-2020', '09:09:50', 'С 8 Марта!', '', 1, '<p><img src="ed/upload-files/images/70x70_2.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/images/600x300_1.jpg" alt="" width="600" height="300" /></p>', '<p>Дорогие наши дамы, поздравляем вас с самым прекрасным праздником весны.&nbsp;Желаем бесконечного счастья и удачи, больше комплиментов и внимания.&nbsp;Оставайтесь всегда красивыми и нежными.&nbsp;Пусть работа будет в радость, а дома ждут вас тишина и покой.</p>\r\n<p>С 8 марта, наши дорогие!</p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><br /><br />Восьмого марта, в день прекрасный,</p>\r\n<p style="text-align: center;">Пусть все цветы для Вас цветут,</p>\r\n<p style="text-align: center;">Пусть наполняет сердце счастье,</p>\r\n<p style="text-align: center;">Мечты пусть крылья обретут!</p>\r\n<p style="text-align: center;"><br /><br /></p>\r\n<p style="text-align: center;">Желаем восхищать собою,</p>\r\n<p style="text-align: center;">Сводить с ума и вдохновлять,</p>\r\n<p style="text-align: center;">Пусть будет жизнь полна любовью,</p>\r\n<p style="text-align: center;">Ведь Вы умеете влюблять!</p>\r\n<p style="text-align: center;"><br /><br /></p>\r\n<p style="text-align: center;">Пусть радость Вас не покидает,</p>\r\n<p style="text-align: center;">Пусть дарят близкие тепло,</p>\r\n<p style="text-align: center;">Мы от души Вас поздравляем</p>\r\n<p style="text-align: center;">С Международным женским днем!</p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><br /><br /></p>', 1, '3166916990', 0),
(530, '09-03-2020', '11:55:35', 'Массовое катание на коньках', '', 1, '<p><img src="ed/upload-files/images/news2016/figurs.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/images/news2016/figurb.jpg" alt="" width="600" height="300" /></p>', '<table border="0" cellspacing="0" cellpadding="0" width="100%">\r\n<tbody>\r\n<tr>\r\n<td width="27">&nbsp;</td>\r\n<td>\r\n<p><strong>УВАЖАЕМЫЕ   КОЛЛЕГИ!<strong>&nbsp;</strong></strong></p>\r\n<p><strong>Организуется   массовое катание для сотрудников и их детей на коньках в СДЮШОР</strong></p>\r\n<p><strong>ПО   ФИГУРНОМУ КАТАНИЮ НА КОНЬКАХ (г. Минск, проезд Каролинский 5/4) :</strong></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>14 марта в 18.45 (45 минут), &nbsp;19.45 (45 минут) и в 20.45 (60 минут).</strong></p>\r\n<p><strong>15 марта в 16.00 (45 минут),&nbsp; 17.00 (45 минут) и в 18.00 &nbsp;(60 минут).</strong></p>\r\n<p><strong>Стоимость проката коньков оплачивать самостоятельно. </strong></p>\r\n<p>Записаться у профгруппоргов отделов до 16.00 &nbsp;10.03.2020.<br /> Профгруппоргам отделов в срок до 17.00 10.03.2020 передать списки желающих (ФИО, отдел, количество (взрослый /детский билет) и дата и время сеанса):</p>\r\n<p><strong>- в здании по пер. Стекольный,5 - каб.616, Савитская Т. Ф., тел. 225-19-16, e-mail: </strong><a title="Отправить письмо" href="mailto:%20ircfr_savitskaya@mnsk.rw">ircfr_savitskaya@mnsk.rw</a><strong>;</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong><br /><img src="ed/upload-files/images/carta.png" alt="" width="581" height="414" /><br /></strong></p>', 1, '3167445335', 0),
(617, '10-01-2022', '16:27:49', 'Проект изменений и дополнений  КОНСТИТУЦИИ РЕСПУБЛИКИ БЕЛАРУСЬ', '', 1, '<p><img src="ed/upload-files/konst2022_m.jpg" alt="" width="80" height="44" /></p>', '<p><img src="ed/upload-files/konst2022_b.jpg" alt="" width="562" height="316" /></p>', '<p style="text-align: center;"><strong>Проект изменений и дополнений КОНСТИТУЦИИ РЕСПУБЛИКИ БЕЛАРУСЬ</strong></p>\r\n<p style="text-align: center;"><br /><br /></p>\r\n<p>С 10.01.2022 в Минске начала работу общественная приемная при Совете Республики по обсуждению изменений и дополнений в Конституцию. График работы: каждый понедельник, среду и пятницу с 11.00 до 17.00 по адресу: г.Минск, ул.Кирова,47.</p>\r\n<p>Также организована работа общественных приемных в каждом из девяти районов Минска при администрациях (график работы общественной приемной администрации Октябрьского района прилагается).</p>\r\n<p>С проектом изменений и дополнений Конституции Республики Беларусь можно ознакомиться:</p>\r\n<p>на сайте Белорусского профессионального союза работников транспорта и коммуникаций belproftrans.1prof.by (Конституцию обсуждаем вместе);</p>\r\n<p>на сайте Pravo.by;</p>\r\n<p>в профсоюзном комитете (у председателя) первичной профсоюзной организации кабинет № 108 по адресу пер. Стекольный,5;</p>\r\n<p>в разделе &laquo;ПРАВОВОЕ ПРОСВЕЩЕНИЕ&raquo;;</p>\r\n<p>на сайте администрации Октябрьского района г.Минска https://okt.minsk.gov.by/vsenarodnoe-obsuzhdenie-proekta.</p>\r\n<p>Мнения граждан относительно содержания проекта изменений и дополнений, а также возможные предложения по его совершенствованию направляются в Национальный центр правовой информации:</p>\r\n<p>по электронной почте&nbsp;<a href="mailto:sbor@ncpi.gov.by">sbor@ncpi.gov.by</a>;</p>\r\n<p>посредством&nbsp;<a title="Сбор замечаний и предложений по проекту Конституции Республики Беларусь" href="https://sbor.pravo.by/" target="_blank">электронной формы</a>;</p>\r\n<p>в письменном виде по адресу 220030, г.&nbsp;Минск, ул.&nbsp;Берсона, 1а, НЦПИ, с пометкой &laquo;Конституция&raquo;.</p>', 1, '3283583269', 0),
(566, '04-03-2021', '14:58:18', 'Дорогие и милые наши дамы!', '', 1, '<p><img src="ed/upload-files/8marta_1.jpg" alt="" width="70" height="57" /></p>', '<p><img src="ed/upload-files/8marta_2.jpg" alt="" width="600" height="488" /></p>', '<p><strong>Дорогие и милые наши дамы!</strong></p>\r\n<p><strong>Поздравляем Вас с самым прекрасным праздником Весны!</strong></p>\r\n<p><br />Желаем счастья и удачи, больше комплиментов и внимания. Оставайтесь всегда красивыми и нежными. Пусть работа будет только в радость, а дома вас ждут спокойствие и любовь.</p>\r\n<p><br />Коллектив РУП "Главный расчетный информационный центр" БЖД.</p>', 1, '3229664298', 0),
(534, '07-04-2020', '10:47:41', 'Правила профилактики респираторных вирусных инфекций (в том числе коронавирусных)', '', 1, '<p><img src="ed/upload-files/korona-small.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/korona.jpg" alt="" width="600" height="300" /></p>', '<p><strong>Правила профилактики респираторных вирусных инфекций (в том числе коронавирусных)</strong></p>\r\n<p><strong><br /></strong></p>\r\n<p><strong>Рекомендации ВОЗ и Минздрав РБ для населения</strong></p>\r\n<p><strong>Правило 1: Соблюдайте гигиену рук!</strong>&nbsp;Чистые руки - это гарантия того, что Вы не будете распространять вирусы, инфицируя себя, когда прикасаетесь ко рту и носу, и окружающих - через поверхности. Как можно чаще, особенно, после пользования общественным транспортом, после любого посещения улицы и общественных мест, перед и после еды, мойте руки водой с мылом или используйте средство для дезинфекции рук.</p>\r\n<p>Носите с собой дезинфицирующее средство для рук или дезинфицирующие салфетки, чтобы иметь возможность в любой обстановке очистить руки. Эти простые меры удалят вирусы с Ваших рук!</p>\r\n<p><strong>Правило 2:&nbsp;</strong>проводите регулярную влажную&nbsp;<strong>уборку помещения</strong>,&nbsp;где Вы находитесь,&nbsp;<strong>чистку и дезинфекцию поверхностей</strong>&nbsp;с использованием бытовых моющих средств. Обратите, прежде всего, внимание на дверные ручки, поручни, столы, стулья, компьютерные клавиатуры и мышки, телефонные аппараты, <strong>общего пользования</strong> и другие предметы, к которым прикасаетесь в быту и на работе. Как можно чаще и регулярно&nbsp;<strong>проветривайте помещение и увлажняйте воздух</strong>&nbsp;любыми доступными способами в помещении, где Вы находитесь.</p>\r\n<p><strong>Правило 3: избегайте многолюдных мест</strong>&nbsp;или сократите время пребывания в местах большого скопления людей (общественный транспорт, торговые центры, концертные залы и др.). Избегайте близкого контакта с людьми, которые кажутся нездоровыми, у которых имеются признаки респираторной инфекции (например, кашляют, чихают). <strong>Избегайте рукопожатий и поцелуев при приветствии</strong> (до прекращения сезона заболеваемости).</p>\r\n<p>Помните, что респираторные вирусы передаются от больного человека к здоровому человеку воздушно-капельным путем (при разговоре, чихании, кашле). Поэтому старайтесь соблюдать расстояние не менее 1-1,5 м от лиц, которые имеют симптомы респираторной инфекции.</p>\r\n<p>&nbsp;Кто вернулся из эпидемиологически неблагополучных по коронавирусу стран не скрывать факт их посещения, по возможности на 14 дней принять меры по так называемой самоизоляции. Не посещать места массового скопления людей, концерты, рестораны, бары или другие крупные мероприятия, сократить посещения родственников старших возрастов. Именно они находятся в особой группе риска, так как заболевание протекает у них тяжелее из-за возрастных изменений в организме и наличия большого &laquo;багажа&raquo; хронических заболеваний.</p>\r\n<p><strong>Соблюдайте &laquo;респираторный этикет&raquo;:</strong></p>\r\n<ul>\r\n<li>прикрывайте рот и нос салфеткой (платком), когда чихаете или кашляете;</li>\r\n<li>используйте одноразовые бумажные салфетки (платки), которые выбрасывайте сразу после использования;</li>\r\n<li>при отсутствии салфетки (платка) кашляйте или чихайте в сгиб локтя;</li>\r\n<li>не касайтесь немытыми руками носа, рта и глаз.<strong>&nbsp; &nbsp; &nbsp;</strong></li>\r\n</ul>\r\n<p><strong>Используйте медицинскую маску,&nbsp;</strong>если:</p>\r\n<p>Вы ухаживаете за больным респираторной инфекцией,</p>\r\n<p>Вы, возможно, будете контактировать с людьми с признаками респираторной инфекции.</p>\r\n<p><strong><em>ВАЖНО!</em></strong><em>&nbsp;При использовании медицинских масок необходимо соблюдать правила:</em></p>\r\n<ol>\r\n<li><em>Обработать руки спиртосодержащим средством или вымыть с мылом.</em></li>\r\n<li><em>Удерживая маску за завязки или резинки вплотную поднести к лицу белой стороной внутрь и фиксировать завязками (резинками) в положении, когда полностью прикрыта нижняя часть лица - и рот, и нос.</em></li>\r\n<li><em>В конце придать нужную форму гибкой полоске (носовому зажиму), обеспечивая плотное прилегание маски к лицу.</em></li>\r\n<li><em>Снять изделие, удерживая за завязки (резинку) сзади, не прикасаясь к передней части маски.</em></li>\r\n<li><em>Выбросить снятую маску в закрывающийся контейнер для отходов.</em></li>\r\n<li><em>Вымыть руки с мылом или обработать спиртосодержащим средством.</em></li>\r\n<li><em>При необходимости надеть новую маску, соблюдая этапы 1-</em>3</li>\r\n</ol>\r\n<p><strong><em>ВАЖНО!&nbsp;</em></strong><em>Использовать маску не более двух часов.</em></p>\r\n<p><em>Немедленно заменить маску в случае ее намокания (увлажнения), даже если прошло менее двух часов с момента использования.</em></p>\r\n<p><em>Не касаться руками закрепленной маски.</em></p>\r\n<p><em>Тщательно вымыть руки с мылом или обработать спиртосодержащим средством после прикосновения к используемой или использованной маске.</em></p>\r\n<p><em>Одноразовые маски нельзя использовать повторно.</em></p>\r\n<p><strong>Правило 4: ведите здоровый образ жизни!</strong>&nbsp;Это повысит естественную сопротивляемость Вашего организма к инфекции.</p>\r\n<p>Чаще совершайте прогулки на свежем воздухе, высыпайтесь и придерживайтесь правил рационального питания (пища должна быть витаминизированной, в особенности богата витаминами А,&nbsp;Bl, С, в пищу должны быть максимально включены овощи, фрукты, особенно содержащие витамин С).</p>\r\n<p><strong>&nbsp;</strong></p>\r\n<p><strong>Правило 5: в случае появления симптомов респираторной инфекции, в том числе гриппа и коронавирусной инфекции (повышение температуры тела, озноб, слабость, головная боль, заложенность носа, конъюнктивит, кашель, затрудненное дыхание, боли в мышцах и чувство &laquo;ломоты&raquo; в теле):</strong></p>\r\n<ul>\r\n<li>оставайтесь дома и вызывайте врача на дом;</li>\r\n<li>если Вы до появления симптомов находились в странах, в которых регистрировались случаи&nbsp;COVID-19 в предыдущие 14 дней, то вызывайте скорую медицинскую помощь и сообщите об этом специалисту;</li>\r\n<li>дети с признаками острой респираторной инфекции должны оставаться дома и не посещать дошкольные учреждения и школы;</li>\r\n<li>строго выполняйте все назначения и рекомендации, которые Вам даст врач (постельный режим, прием лекарственных средств);</li>\r\n<li>максимально ограничьте свои контакты с домашними, особенно детьми, пожилыми людьми и лицами, страдающими хроническими заболеваниями, чтобы не заразить их;</li>\r\n<li>используйте медицинскую маску, если Вы вынуждены контактировать с людьми.</li>\r\n</ul>\r\n<p>Помните, что&nbsp;своевременное обращение к врачу&nbsp;и начатое лечение позволит минимизировать риск развития и степень тяжести основного осложнения гриппа и коронавирусной инфекции - пневмонии.</p>\r\n<p><strong>Обращаем внимание!!! &nbsp;</strong>После выписки из лечебного учреждения граждане не являются носителями коронавирусной<strong>&nbsp;</strong>инфекции</p>\r\n<p><strong><br /></strong></p>', 1, '3172452461', 0),
(536, '16-04-2020', '10:24:54', 'Об открытии благотворительного фонда', '', 1, '<p><img src="ed/upload-files/images/doctor_70x70.jpg" alt="" width="70" height="58" /></p>', '<p><img src="ed/upload-files/images/doctor1_600x300.jpg" alt="" width="600" height="300" /></p>', '<p>Об открытии благотворительного счета</p>\r\n<p><br />В рамках акции &laquo;Справимся вместе!&raquo; при Белорусском профсоюзе работников здравоохранения создан Фонд поддержки работников организаций здравоохранения, участвующих в оказании медицинской помощи пациентам с заболеваниями COVID-19. Для сбора, хранения и использования средств фонда открыт благотворительный счет.</p>\r\n<p>Номер благотворительного счета: BY06 BLBB 3135 0100 0948 7400 1001, открыт в Дирекции ОАО &laquo;Белинвестбанк&raquo; по г. Минску и Минской области, код BLBBBY2X, получатель средств - Белорусский профсоюз работников здравоохранения, УНП 100094874.</p>\r\n<p>Обращаем Ваше внимание, что физические лица также могут произвести перечисления денежных средств на благотворительный счет в системе ЕРИП в любом банке (интернет-банкинге, мобильном банкинге, инфокиоске, банкомате, кассе и т.д.). Совершить оплату можно с использованием наличных денежных средств, банковских платежных карточек либо любых электронных денег.</p>\r\n<p><span style="text-decoration: underline;"><strong>Для проведения платежа необходимо следовать четкой&nbsp;</strong><strong>пошаговой инструкции, а именно:</strong></span></p>\r\n<p>1. Выбрать пункт&nbsp;<em>&laquo;Система &laquo;Расчет&raquo; (ЕРИП)</em></p>\r\n<p><em>2. Благотворительность, общественные объединения</em></p>\r\n<p><em>3. Профсоюзы</em><em>&nbsp;</em></p>\r\n<p><em>4. Профсоюз здравоохранения</em></p>\r\n<p>5. Для оплаты ввести&nbsp;<em>Фамилию Имя Отчество плательщика</em>,&nbsp;<em>дополнительно укажите наименование организации</em></p>\r\n<p>6. Ввести сумму платежа</p>\r\n<p>7. Проверить корректность информации</p>\r\n<p>8. Совершить платеж.</p>\r\n<p>Особое внимание обращаем на то, что в настоящее время в &laquo;Системе &laquo;Расчет&raquo; (ЕРИП) открыты и иные благотворительные счета, в связи с этим необходимо придерживаться&nbsp;<span style="text-decoration: underline;">точной пошаговой инструкции</span>, описанной выше для того, чтобы денежные средства были зачислены именно на благотворительный счет, открытый Белорусским профсоюзом работников здравоохранения.</p>\r\n<p>Настоящую информацию просим довести до всех заинтересованных.<em>&nbsp;</em></p>\r\n<p><em><br /><em><strong><a href="ed/upload-files/docs/REKVIZITY_BPRZ.docx">РЕКВИЗИТЫ ДЛЯ ПЕРЕВОДА ДЕНЕЖНЫХ СРЕДСТВ</a></strong></em><br /></em></p>', 1, '3174006294', 0),
(537, '17-04-2020', '11:50:01', 'Рекомендации  по социальному дистанцированию  в период регистрации  коронавирусной инфекции', '', 1, '<p><img src="ed/upload-files/images/people_70x70.png" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/images/people_600x300.png" alt="" width="600" height="300" /></p>', '<p style="text-align: center;"><strong>Рекомендации </strong></p>\r\n<p style="text-align: center;"><strong>по социальному дистанцированию </strong></p>\r\n<p style="text-align: center;"><strong>в период регистрации </strong></p>\r\n<p style="text-align: center;"><strong>коронавирусной инфекции</strong></p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p><br /><strong>Цель&nbsp; социального дистанцирования</strong> &mdash; снижение вероятности контакта между инфицированными и неинфицированными людьми, чтобы уменьшить уровень передачи инфекции.</p>\r\n<p><strong>Принцип&nbsp; социального дистанцирования</strong> -&nbsp; человек организует свою жизнь таким образом, чтобы сократить на 3/4 контакты за пределами дома и работы, и на 1/4 - на работе.</p>\r\n<p>Если люди практикуют &laquo;социальное дистанцирование&raquo;, избегая общественных мест и в принципе ограничивая свои передвижения, распространение инфекции замедляется, происходит сдерживание взрывного роста распространения вируса.</p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><strong>Рекомендации:</strong></p>\r\n<p>1. Не выходите из дома, если в этом нет особой надобности (поездка на работу, покупка продуктов питания и лекарств, получение медицинских и других жизненно важных услуг).</p>\r\n<p>2. Не выходите из дома для посещения тех мест, посещение которых не является жизненно важным (библиотек, музеев, кинотеатров, театров и других общественных мест). Дети могут выходить только с семьей. Организуйте выгул домашних животных в одиночку.</p>\r\n<p>3. Воздержитесь от посещения занятий в кружках, спортивных клубах, тренажерных залах, даже с минимальным количеством участников. В случае, если Вы продолжаете спортивные занятия, убедитесь, что численность группы не превышает 5 человек и во время занятий соблюдается расстояние 1,5-2 м между людьми.</p>\r\n<p>4. Общайтесь с другими людьми дистанционно с помощью средств связи. Не следует ходить в гости и принимать у себя друзей и членов семьи, которые не проживают с вами.</p>\r\n<p>5. Для сокращения потребности выходить из дома можно использовать следующие меры:</p>\r\n<p>&nbsp; &nbsp; удаленная работа, видеозвонки и конференц-связь;</p>\r\n<p>&nbsp; &nbsp; каждый работодатель должен следить за сохранением дистанции в 1 - 1,5 метра между рабочими местами сотрудников, соблюдением правил личной гигиены и гигиены окружающей среды&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;(помещения);</p>\r\n<p>&nbsp; &nbsp; выбирать услуги доставки - только до порога квартиры (дома, офиса);</p>\r\n<p>&nbsp; &nbsp; обращение за стоматологической помощью рекомендуется отложить, за исключением неотложных случаев.</p>\r\n<p>6. Если Вы выходите из дома в ситуациях, когда это необходимо (см. п.1.), необходимо сократить контакты с другими людьми и сохранять 1,5-2 метровое расстояние друг от друга.</p>\r\n<p>7. Рекомендации для людей из группы высокого риска - лиц старшего и пожилого возраста, лиц с хроническими заболеваниями любого возраста (заболевания органов дыхания, бронхиальная астма, заболевания сердечнососудистой системы, иммунной системы, онкологические заболевания). Вам желательно вообще не выходить из дома, насколько это возможно. Не принимайте никого у себя дома, за исключением необходимости получения жизненно важных услуг.</p>\r\n<p>Попросите родных и знакомых помочь Вам с обеспечением бытовых потребностей.</p>\r\n<p>8. В случае необходимости получения медицинских помощи, желательно использовать дистанционные медицинские услуги, без посещения поликлиники.</p>\r\n<p>Если Вы старше 60 лет и нуждаетесь в осмотре медицинского работника в связи с ухудшением самочувствия, позвоните в регистратуру, стол справок или колл-центр учреждения здравоохранения по месту жительства, сообщите об этом,&nbsp; оставьте контакты (ФИО, адрес, телефон), в течение рабочего дня с Вами свяжется медицинский работник и согласует время для визита на дом.</p>\r\n<p>Если Вы нуждаетесь в выписке рецептов на лекарственные средства для постоянного приема, ранее назначенные врачом, позвоните в регистратуру, стол справок или колл-центр учреждения здравоохранения по месту жительства, оставьте контакты (ФИО, адрес, телефон), с Вами свяжется медицинский работник, который организует выписку и доставку рецептов на дом.</p>\r\n<p>С целью реализации пункта 9 приложения 4 к приказу Министерства здравоохранения Республики Беларусь от 16.03.2020 № 296 &laquo;О мерах по организации оказания медицинской помощи пациентам с признаками респираторной инфекции и принятию дополнительных противоэпидемических мер в организациях здравоохранения&raquo;</p>\r\n<p>В общественных местах соблюдать расстояние 1-1,5 м от других людей.</p>\r\n<p>Соблюдать гигиену рук и респираторный этикет.</p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><strong>Как вести себя на работе:</strong></p>\r\n<p>Соблюдать расстояние 1-1,5 м между рабочими местами сотрудников.</p>\r\n<p>Минимизировать личные контакты. Использовать телефонную и компьютерную связь для решения рабочих вопросов.</p>\r\n<p>Чаще мыть руки, обрабатывать спиртосодержащим антисептиком, гелем, салфетками).</p>\r\n<p>Стараться не касаться носа и рта. Использовать, при необходимости, одноразовые бумажные платки, полотенца, салфетки.</p>\r\n<p>&nbsp;</p>\r\n<p>(Администрация Московского района г. Минска)</p>', 1, '3174184201', 0),
(758, '24-10-2023', '08:03:23', 'НАЛОГОВАЯ НАПОМИНАЕТ - ДО 15 НОЯБРЯ СРОК УПЛАТЫ ГРАЖДАНАМИ НАЛОГОВ', '', 1, '<p><img src="ed/upload-files/nalogg.JPG" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/nalogg.JPG" alt="" width="600" height="300" /></p>', '<p style="text-align: center;"><a href="ed/upload-files/nalog2023.pdf"></a><strong><span style="font-size: x-large;"><a href="ed/upload-files/nalog2023.pdf" target="_blank">...ПРЕЗЕНТАЦИЯ....</a></span></strong></p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><strong><span style="font-size: x-large;"><br /></span></strong></p>', 1, '3396218603', 0),
(759, '03-11-2023', '17:09:43', 'Победители соревнования по боулингу!!!', '', 1, '<p><img src="ed/upload-files/bowling70_70_2.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/docs/Bouling/Bouling_23.jpg" alt="" width="600" height="300" /></p>', '<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-family: helvetica; font-size: large; color: #000000;"><strong>Лучшие командные результаты</strong></span></p>\r\n<table style="margin-left: auto; margin-right: auto;" border="1" cellspacing="0" cellpadding="0">\r\n<tbody>\r\n<tr>\r\n<td width="73" valign="top">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width="208" valign="top">\r\n<p><span style="color: #000000;"><strong>&nbsp; &nbsp;Название команды</strong></span></p>\r\n</td>\r\n<td width="151" valign="top">\r\n<p><span style="color: #000000;"><strong>&nbsp; &nbsp; Общий   балл</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: center;" width="73" valign="top">\r\n<p><span style="color: #000000;"><strong>1</strong></span></p>\r\n<p><span style="color: #000000;"><strong><br /></strong></span></p>\r\n</td>\r\n<td style="text-align: center;" width="208" valign="top">\r\n<p><span style="color: #000000;"><strong>&laquo;На третьем&raquo; (г. Жлобин)</strong></span></p>\r\n</td>\r\n<td style="text-align: center;" width="151" valign="top">\r\n<p><span style="color: #000000;"><strong>761</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: center;" width="73" valign="top">\r\n<p><span style="color: #000000;"><strong>2</strong></span></p>\r\n</td>\r\n<td style="text-align: center;" width="208" valign="top">\r\n<p><span style="color: #000000;"><strong>&laquo;Потешные чебуреки&raquo; (г. Гомель)</strong></span></p>\r\n</td>\r\n<td style="text-align: center;" width="151" valign="top">\r\n<p><span style="color: #000000;"><strong>713</strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style="text-align: center;" width="73" valign="top">\r\n<p><span style="color: #00