(715, '16-03-2023', '08:12:13', '17 марта 2023 года – 85 лет Октябрьскому району г.Минска. ', '', 1, '<p><img src="ed/upload-files/2023/224.PNG" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2023/224.PNG" alt="" width="600" height="300" /></p>', '<pre style="text-align: center;"><span style="font-family: &quot;times new roman&quot;, times; font-size: large;"><strong><a href="ed/upload-files/videonew/123.mp4">...Фильм Октябрьский район 2023...</a></strong></span></pre>\r\n<pre style="text-align: center;"><img src="ed/upload-files/2023/234.JPG" alt="" width="618" height="868" /></pre>', 1, '3357857533', 0),
(716, '21-03-2023', '10:00:50', '80 лет Хатынской трагедии', '', 1, '<p><img src="ed/upload-files/2023/raion.jpg\r\n" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2023/raion.jpg\r\n" alt="" width="600" height="300" /></p>', '<p style="text-align: center;"><span style="font-size: large; color: #000000;">В рамках проводимой общереспубликанской акции <strong>22.03.2023</strong> на предприятии&nbsp; в <strong>12.00</strong> проводится минута молчания посвященная жертвам Хатынской трагедии.</span></p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><strong><span style="font-size: large; color: #000000;"><a href="ed/upload-files/2023/info.pdf">.....Информация по трагедии в Хатыне.....</a><br /></span></strong></p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-size: large;"><strong><a href="ed/upload-files/video/80_rolik.mp4">...РОЛИК "80 лет Хатынской трагедии".....</a></strong></span></p>\r\n<p style="text-align: center;"><span style="font-size: large;"><strong><br /></strong></span></p>\r\n<p style="text-align: center;"><span style="font-size: large;"><strong><a href="ed/upload-files/2023/44.mp3">....Аудиоролик для минуты молчания в 12.00 22.03.2023....</a></strong></span></p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><span style="font-size: large;"><strong><img src="ed/upload-files/2023/33.jpg" alt="" width="424" height="600" /><br /></strong></span></p>', 1, '3358728050', 0),
