(858, '10-07-2024', '09:42:07', 'ВСЕМИРНЫЙ ДЕНЬ НАРОДОНАСЕЛЕНИЯ', '0712', 1, '<p><img src="ed/upload-files/2024/388.PNG" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/34.PNG" alt="" width="600" height="282" /></p>', '<p style="text-align: center;"><strong><span style="font-size: large;"><a href="ed/upload-files/2024/statobzor_narod-2024_1.pdf" target="_blank">Статистический обзор</a></span></strong></p>', 1, '3441152527', 0),
(859, '15-07-2024', '13:46:53', 'Смотрите "Минский курьер"', '0722', 0, '<p><img src="ed/upload-files/2024/MK_b.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/MK_b.jpg" alt="" width="600" height="323" /></p>', '<p style="text-align: center;"><span style="font-size: medium; color: #000000;"><strong>Смотрите "Минский курьер.</strong>&nbsp;Обзор событий с 08 по 14 июля<strong>"</strong>&nbsp;на YouTube</span></p>\r\n<p style="text-align: center;"><span><span style="font-size: medium; color: #000000;"><a href="https://youtu.be/-D6-_DL7Sek?feature=shared" target="_blank">https://youtu.be/hwgb-jy4sxs?feature=shared&nbsp;</a></span><br /></span></p>', 1, '3442031513', 0),
(860, '18-07-2024', '12:53:25', 'Республиканский конкурс творческих работ', '1001', 1, '<p><img src="ed/upload-files/2024/55555.png" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/88889.png" alt="" width="688" height="272" /></p>', '<p><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span><span style="color: #000000; font-size: medium;">Администрация Октябрьского района г.Минска приглашает принять участие в проводимом Национальной академией наук Беларуси Республиканском конкурсе творческих работ, посвященном Году качества.</span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span>В рамках конкурса Центр исследований белорусской культуры, языка и литературы НАН Беларуси выдвигает номинацию, на которую могут быть представлены работы, прославляющие традиции народного труда, посвященные юбилейной дате освобождения Беларуси от немецко-фашистских захватчиков и исторической памяти, а также произведения народных мастеров, мастеров декоративно-прикладного искуства, народных творческих коллективов, изделия школьных творческих кружков.</span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span>Условия конкурса, требования к работам и участникам, порядок рассмотрения работ и другие вопросы организации и проведения конкурса изложены в Положении о Республиканском конкурсе творческих работ, посвященном Году качества (прилагается), также с Положением можно ознакомится по ссылке: <a href="ed/upload-files/2024/docs/polozenie.pdf" target="_blank">положение.pdf</a> (<a href="ed/upload-files/2024/docs/polozenie.pdf" target="_blank">открыть</a>) .</span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span>Работы, рекомендованные для участия в конкурсе и оформленные согласно Положению, просим направлять в одном экземпляре до 01.10.2024 в Национальную академию наук Беларуси по адресу: 220072, г.Минск, пр.Независимости, д.66.</span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span><span style="text-decoration: underline;"><a href="ed/upload-files/2024/docs/zayavka.docx">Заявка на участие в конкурсе в текстовом редакторе Microsoft World</a></span> (<a href="ed/upload-files/2024/docs/zayavka.docx">скачать</a>) , оформленная согласно установленной форме (прилагается), дополнительно направляется на электронный адрес: humanity@presidium.bas-net.by.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><span style="color: #000000; font-size: medium;"><strong>Приглашаем к участию в конкурсе и желаем удачи!</strong></span></p>', 1, '3442546405', 0),
(861, '22-07-2024', '15:41:09', 'Благотворительность', '0726', 0, '<p><img src="ed/upload-files/2024/IMG_0789.PNG" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/IMG_0789.PNG" alt="" width="600" height="272" /></p>', '<p><img style="display: block; margin-left: auto; margin-right: auto;" src="ed/upload-files/2024/blag_22.07.2024.jpg" alt="" width="560" height="996" /></p>', 1, '3443247669', 0),
(862, '22-07-2024', '15:58:26', 'Накопительная пенсия с участием государства', '0726', 1, '<p><img src="ed/upload-files/2024/af_ikon.png" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/aff_2207.png" alt="" width="600" height="272" /></p>', '<p style="text-align: center;"><img src="ed/upload-files/2024/afisha_2207.jpg" alt="" width="540" height="757" /></p>', 1, '3443248706', 0),
(863, '23-07-2024', '12:45:44', 'Смотрите "Минский курьер"', '0727', 0, '<p><img src="ed/upload-files/2024/MK_b.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/MK_b.jpg" alt="" width="600" height="323" /></p>', '<p style="text-align: center;"><span style="font-size: medium; color: #000000;"><strong>Смотрите "Минский курьер.</strong>&nbsp;Обзор событий с 15 по 21 июля<strong>"</strong>&nbsp;на YouTube</span></p>\r\n<p style="text-align: center;"><span><span style="font-size: medium; color: #000000;"><a href="https://youtu.be/-D6-_DL7Sek?feature=shared" target="_blank">https://youtu.be/eApk1bVP9Rk?feature=shared</a></span><br /></span></p>', 1, '3443404544', 0);
INSERT INTO `news` (`id`, `date`, `time`, `news`, `newsrash`, `key_news`, `fotosmall`, `fotobig`, `bigtext`, `newsrash1`, `dt`, `securit`) VALUES
(864, '23-07-2024', '16:47:16', 'Конкурс "Вместе против коррупции"', '0915', 1, '<p><img src="ed/upload-files/2024/log_konk.jpg" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/IMG_0797.JPG" alt="" width="600" height="272" /></p>', '<p style="text-align: center;"><span style="color: #4856fe;"><strong><span style="font-size: large;">Для возможного участия</span></strong></span></p>\r\n<p style="text-align: center;"><span style="color: #4856fe;"><strong><span style="font-size: large;"><strong><span><a href="ed/upload-files/2024/konkurs_proved_korup.PDF" target="_blank">...Положение о проведении конкурса.pdf...</a></span></strong></span></strong></span></p>\r\n<p style="text-align: center;"><span style="color: #4856fe;"><strong><span style="font-size: large;"><strong><span><br /></span></strong></span></strong></span></p>', 1, '3443424436', 0),
(865, '24-07-2024', '11:44:14', 'Единый день безопасности дорожного движения', '0727', 1, '<p><img src="ed/upload-files/2024/pdd3.png" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/pdd1.png" alt="" width="600" height="300" /></p>', '<p style="text-align: center;"><span style="color: #000000; font-size: large;"><strong>26 июля Единый день безопасности дорожного движения </strong></span></p>\r\n<p style="text-align: center;"><span style="color: #000000; font-size: large;"><strong>&laquo;Сел в машину &ndash; пристегни ремень!&raquo;</strong></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style="color: #000000;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span><span style="font-size: medium;">Все мероприятия, проводимые сотрудниками Госавтоинспекции в этот день, будут направлены на пропаганду использования средств пассивной безопасности (ремни, шлемы, детские удерживающие устройства).</span></span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span>Согласно пункту 9.5 ПДД Республики Беларусь водитель обязан быть пристегнутым и не перевозить пассажиров с непристегнутыми ремнями безопасности при движении в механическом транспортном средстве, оборудованном ремнями безопасности, а при движении на мотоцикле, мопеде &ndash; быть в застегнутом мотошлеме и не перевозить пассажиров без застегнутого мотошлема.</span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span>Несоблюдение водителями и пассажирами правил использования ремней безопасности и мотошлемов является одной из сопутствующих причин высокой тяжести последствий ДТП.</span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span>За нарушение правил пользования ремнями безопасности и мотошлемами предусмотрена ответственность водителя в виде штрафа в размере до одной базовой величины. За повторное в течение года нарушение этого требования правил с водителя взыскивается штраф в размере от двух до пяти базовых величин.</span></p>\r\n<p><span style="color: #000000; font-size: medium;"><span style="white-space: pre;"> <span style="white-space: pre;"> </span></span>За нарушение правил перевозки детей в салоне автомобиля предусмотрена ответственность в виде штрафа до четырех базовых величин.</span></p>\r\n<p>&nbsp;</p>\r\n<p style="text-align: center;"><video controls='''' src=''http://www.rw/ed/upload-files/2024/gai_2024.mp4'' width="543" height="422"></video>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<img src="ed/upload-files/2024/2pdd.png" alt="" width="543" height="375" /></p>\r\n<p style="text-align: center;">&nbsp;</p>\r\n<p style="text-align: center;"><span style="color: #000000; font-size: medium;"><em>Берегите себя и окружающих!</em></span></p>\r\n<p style="text-align: center;"><em><br /></em></p>', 1, '3443579054', 0),
(866, '25-07-2024', '16:44:09', '30 лет национальной доменной зоне BY', '0730', 1, '<p><img src="ed/upload-files/2024/22301.png" alt="" width="70" height="70" /></p>', '<p><img src="ed/upload-files/2024/2230.png" alt="" width="600" height="272" /></p>', '<h2 style="text-align: center;"><span style="color: #000000;">30 лет национальной доменной зоне BY</span></h2>', 1, '3443768529', 0),
