INSERT INTO `richstone_page` (`id`, `richstone_page_name`, `richstone_page_source`, `richstone_page_view_flag`, `key_menu`, `key_menu_num`, `key_num`, `menu`, `menu_num`, `alt_name`, `date`, `time`, `dt`, `redakt`, `izmena`, `nameotd`, `securit`, `skrito`) VALUES
(1, 'Главная', '<table border="0" cellspacing="0" cellpadding="0" width="100%">\r\n<tbody>\r\n<tr>\r\n<td class="ott">\r\n<h1>&nbsp;Администрация ресурса рада приветствовать вас на Официальном сайте РУП "Главный расчетный информационный центр" БЖД</h1>\r\n<p><strong>Важная информация! </strong><strong>&nbsp;</strong><strong>&nbsp;</strong></p>\r\n<p>Прогноз погоды на сайте показывается для того города, из которого вы зашли на сайт.</p>\r\n<p>Для корректного отображения web-сайта, необходимо обновить свой браузер, данное обновление требуется если установлен Internet Explorer 5,6. Обновить этот и другие браузеры можно через&nbsp;страницу - "<a class="spis3" href="?link=83">Интернет браузеры</a>".</p>\r\n<p>Поиск на сайте работает по ФИО, телефону, комнате и отделу. Ввод данных в поле поиска можно осуществлять с заглавных и прописных букв, с русской и английской раскладки клавиатуры. В поиск включены работники отделов предприятия РУП "Главный расчетный информационный центр БЖД"&nbsp;<strong>.</strong></p>\r\n<p>В поиск добавлена новая функция! Теперь при поиске человека в справочнике можно увидеть, когда будет его день рождения!</p>\r\n<p>Можно отправлять письма c сайта при поиске человека или с общего списка отдела, но только если есть запись с e-mail. Осуществляется это при нажатии на фото или аватар человека.</p>\r\n<p>Для своевременного получения информации на сайте, необходимо подписаться на информационные ресурсы соответствующей тематики.</p>\r\n<p>&nbsp;</p>\r\n<h1><strong style="text-transform: uppercase;">НОВОСТИ НА ОФИЦИАЛЬНЫХ КАНАЛАХ БЖД В СОЦИАЛЬНЫХ СЕТЯХ</strong><span style="text-transform: uppercase;">&nbsp;:</span><span style="text-transform: uppercase;"><a href="https://vk.com/belrw_official"> </a></span><span style="text-transform: uppercase;"><a href="https://vk.com/belrw_official"><img src="ed/upload-files/logos/VK.png" alt="" width="20" height="20" /></a> <a href="https://twitter.com/belrw_official"><img src="ed/upload-files/logos/Twitter.png" alt="" width="20" height="20" /></a> <a href="https://www.facebook.com/belrw_official"><img src="ed/upload-files/logos/Facebook.png" alt="" width="20" height="20" /></a> <a href="https://invite.viber.com/?g2=AQBCFtCCOu%2FCtUnavBb2YNIsoWGL3KH1OHmrqJFk97dCtgVLs54DZfcVuKPw%2FNxp"><img src="ed/upload-files/logos/Viber.png" alt="" width="20" height="20" /></a> <a href="https://t.me/belrw_official"><img src="ed/upload-files/logos/Telegram.png" alt="" width="20" height="20" /></a></span></h1>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style="text-transform: uppercase;"><br /><br /></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', 1, 0, 0, 0, 0, 0, 0, '30-01-2025', '09:06:13', '', 0, 0, '', 1, 0),
