INSERT INTO `richstone_page` (`id`, `richstone_page_name`, `richstone_page_source`, `richstone_page_view_flag`, `key_menu`, `key_menu_num`, `key_num`, `menu`, `menu_num`, `alt_name`, `date`, `time`, `dt`, `redakt`, `izmena`, `nameotd`, `securit`, `skrito`) VALUES
(173, 'Велопробег 2015', '<table border="0" cellspacing="0" cellpadding="0" width="100%">\r\n<tbody>\r\n<tr>\r\n<td class="tl" width="27" height="26">&nbsp;</td>\r\n<td class="tc">&nbsp;</td>\r\n<td class="tr" width="27" height="26">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class="ml" width="27" height="26">\r\n<p>&nbsp;</p>\r\n<p><br /><br /></p>\r\n</td>\r\n<td class="mc">\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<strong> 22 &nbsp;июня в Бресте стартовал второй маршрут велопробега, посвященного&nbsp;70-летию Победы в Великой Отечественной войне и 110-летию образования профсоюза железнодорожников.</strong></p>\r\n<p>В крупномасштабном спортивно-массовом мероприятии принимает участие и&nbsp;команда &nbsp; Белорусской &nbsp; железной &nbsp; дороги &nbsp; в &nbsp;составе &nbsp;7 &nbsp;человек &nbsp;&mdash;&nbsp;представителей &nbsp; отделений &nbsp;белорусской &nbsp;магистрали.</p>\r\n<p><strong>От &nbsp;РУП &nbsp;"Главный&nbsp;расчетный &nbsp;центр" &nbsp;в велопробеге принимает участие Нехайчик Александр&nbsp;Владимирович - &nbsp;заместитель начальника отдела технических средств.&nbsp;</strong></p>\r\n<p>Город Брест стал вторым маршрутом велопробега. Первый маршрут стартовал в Хабаровске 12 апреля.После Бреста эстафету примет 10 июля город Севастополь.</p>\r\n<p>Завершится мероприятие финишем 29 июля в Волгограде на Мамаевом кургане &mdash; месте, сыгравшем решающую роль в ходе Великой Отечественной войны.&nbsp;</p>\r\n<p>В Бресте в программе акции предусмотрен митинг, возложение цветов к памятным местам ГУ &laquo;Мемориальный комплекс &laquo;Брестская крепость-герой&raquo;.</p>\r\n<p>Участие команды Белорусской железной дороги по территории Беларуси планируется по маршруту Брест&ndash;Невель, через Пружаны, Слоним, Несвиж, Минск, Логойск, Лепель, Городок с 22 по 30 июня.</p>\r\n<p>Всего участники велопробега намерены преодолеть около восьми тысяч километров.</p>\r\n<p>Организатором мероприятия на территории Беларуси выступили Белорусский профессиональный союз железнодорожников и транспортных строителей и Белорусская железная дорога.</p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015621193941.jpg" alt="" width="700" height="525" /></p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015622083010.jpg" alt="" width="700" height="525" /></p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015622085749.jpg" alt="" width="700" height="525" /></p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015622090714.jpg" alt="" width="700" height="525" /></p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015622091855.jpg" alt="" width="700" height="525" /></p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015622092200.jpg" alt="" width="700" height="525" /></p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015622100030.jpg" alt="" width="700" height="525" /></p>\r\n<p><img src="ed/upload-files/images/news/veloprobeg/2015622100048.jpg" alt="" width="700" height="525" /></p>\r\n</td>\r\n<td class="mr" width="27" height="26">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class="bl" width="27" height="26">&nbsp;</td>\r\n<td class="bc">&nbsp;</td>\r\n<td class="br" width="27" height="26">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>Велопробег 2015</p>', 1, 0, 0, 0, 0, 0, 0, '24-06-2015', '12:51:22', '2870225482', 0, 0, '', 0, 0),
(65, 'Разное', '<table border="0" cellspacing="0" cellpadding="0" width="100%">\r\n<tbody>\r\n<tr>\r\n<td class="tl" width="27" height="26">&nbsp;</td>\r\n<td class="tc">&nbsp;</td>\r\n<td class="tr" width="27" height="26">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class="ml" width="27" height="26">&nbsp;<strong>&nbsp;</strong></td>\r\n<td class="mc">\r\n<table style="border-collapse: collapse;" border="0" cellspacing="0" cellpadding="0" width="100%">\r\n<tbody>\r\n<tr>\r\n<td class="zag1" style="text-align: center;">Обновления</td>\r\n<td class="zag1" style="text-align: center;">Скачать</td>\r\n</tr>\r\n<tr>\r\n<td class="spis">Документ "Результаты обследования" подсистемы "Управление материально - техническим снабжением"</td>\r\n<td class="spis" style="text-align: center;"><a class="link" href="ed/upload-files/docs/inform_resursi_servera/ek_isyfr/raznoe/rezob.doc">Скачать</a></td>\r\n</tr>\r\n<tr>\r\n<td class="spis">Документ "КП НОКС - Концептуальный проект "Ведение учета объектов незавершенного капитального строительства по видам работ и оборудованию к установке"</td>\r\n<td class="spis" style="text-align: center;"><a class="link" href="ed/upload-files/docs/inform_resursi_servera/ek_isyfr/raznoe/kp_noks.doc">Скачать</a></td>\r\n</tr>\r\n<tr>\r\n<td class="spis">Обновление bi710sp15 для SAP BW BI 7.10</td>\r\n<td class="spis" style="text-align: center;"><a class="link" href="ed/upload-files/docs/inform_resursi_servera/ek_isyfr/raznoe/bi710sp15_1500-10004472.exe">Скачать</a></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</td>\r\n<td class="mr" width="27" height="26">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class="bl" width="27" height="26">&nbsp;</td>\r\n<td class="bc">&nbsp;</td>\r\n<td class="br" width="27" height="26">&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>', 1, 0, 0, 0, 0, 0, 0, '29-09-2022', '16:21:32', '3328856492', 0, 0, '', 0, 0),
